// TakePending implements mm_auth.SessionStore
func (mmTakePending *SessionStoreMock) TakePending(ctx context.Context, challenge string) (userID string, epoch int64, err error) {
	mm_atomic.AddUint64(&mmTakePending.beforeTakePendingCounter, 1)
	defer mm_atomic.AddUint64(&mmTakePending.afterTakePendingCounter, 1)

	mmTakePending.t.Helper()

	if mmTakePending.inspectFuncTakePending != nil {
		mmTakePending.inspectFuncTakePending(ctx, challenge)
	}

	mm_params := SessionStoreMockTakePendingParams{ctx, challenge}

	// Record call args
	mmTakePending.TakePendingMock.mutex.Lock()
	mmTakePending.TakePendingMock.callArgs = append(mmTakePending.TakePendingMock.callArgs, &mm_params)
	mmTakePending.TakePendingMock.mutex.Unlock()

	for _, e := range mmTakePending.TakePendingMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.userID, e.results.epoch, e.results.err
		}
	}

	if mmTakePending.TakePendingMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmTakePending.TakePendingMock.defaultExpectation.Counter, 1)
		mm_want := mmTakePending.TakePendingMock.defaultExpectation.params
		mm_want_ptrs := mmTakePending.TakePendingMock.defaultExpectation.paramPtrs

		mm_got := SessionStoreMockTakePendingParams{ctx, challenge}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmTakePending.t.Errorf("SessionStoreMock.TakePending got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmTakePending.TakePendingMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.challenge != nil && !minimock.Equal(*mm_want_ptrs.challenge, mm_got.challenge) {
				mmTakePending.t.Errorf("SessionStoreMock.TakePending got unexpected parameter challenge, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmTakePending.TakePendingMock.defaultExpectation.expectationOrigins.originChallenge, *mm_want_ptrs.challenge, mm_got.challenge, minimock.Diff(*mm_want_ptrs.challenge, mm_got.challenge))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmTakePending.t.Errorf("SessionStoreMock.TakePending got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmTakePending.TakePendingMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmTakePending.TakePendingMock.defaultExpectation.results
		if mm_results == nil {
			mmTakePending.t.Fatal("No results are set for the SessionStoreMock.TakePending")
		}
		return (*mm_results).userID, (*mm_results).epoch, (*mm_results).err
	}
	if mmTakePending.funcTakePending != nil {
		return mmTakePending.funcTakePending(ctx, challenge)
	}
	mmTakePending.t.Fatalf("Unexpected call to SessionStoreMock.TakePending. %v %v", ctx, challenge)
	return
}

